<?php $activities = sd_homepage_activities(); if ( empty( $activities ) ) { return; } ?><section class="sd-home-section sd-home-discussions"><div class="sd-container"><?php sd_homepage_heading( __( 'Conversation', 'social-discovery' ), sd_homepage_get( 'sd_home_discussions_heading' ), __( 'Public activity from the community, when BuddyPress is available.', 'social-discovery' ) ); ?><div class="sd-home-discussion-list"><?php foreach ( $activities as $activity ) : ?><article class="sd-home-discussion"><div class="sd-home-discussion-avatar"><img src="<?php echo esc_url( sd_avatar( $activity->user_id, 56 ) ); ?>" alt="" loading="lazy"></div><div><h3><?php echo esc_html( function_exists( 'bp_core_get_user_displayname' ) ? bp_core_get_user_displayname( $activity->user_id ) : __( 'Member', 'social-discovery' ) ); ?></h3><time datetime="<?php echo esc_attr( get_date_from_gmt( gmdate( 'Y-m-d H:i:s', strtotime( $activity->date_recorded ) ), 'c' ) ); ?>"><?php echo esc_html( bp_core_get_last_activity( $activity->user_id, $activity->date_recorded ) ); ?></time><p><?php echo esc_html( wp_trim_words( wp_strip_all_tags( $activity->content ), 32 ) ); ?></p><?php if ( function_exists( 'bp_activity_get_permalink' ) ) : ?><a class="sd-text-link" href="<?php echo esc_url( bp_activity_get_permalink( $activity ) ); ?>"><?php esc_html_e( 'Read discussion', 'social-discovery' ); ?> <span aria-hidden="true">→</span></a><?php endif; ?></div></article><?php endforeach; ?></div></div></section>
